// lib/shard/src/operations/payload_ops.rs:16-27 — explicit design-intent doc comments on the two op variants
pub enum PayloadOps {
    /// Set payload value, overrides if it is already exists
    SetPayload(SetPayloadOp),
    /// Deletes specified payload values if they are assigned
    DeletePayload(DeletePayloadOp),
    /// Drops all Payload values associated with given points.
    ClearPayload { points: Vec<PointIdType> },
    /// Clear all Payload values by given filter criteria.
    ClearPayloadByFilter(Filter),
    /// Overwrite full payload with given keys
    OverwritePayload(SetPayloadOp),
}

// src/actix/api/update_api.rs:194-195, 227-228 — same URL, two verbs, two handlers
#[post("/collections/{collection_name}/points/payload")]
async fn set_payload(...) { ... let res = do_set_payload(...) ... }
#[put("/collections/{collection_name}/points/payload")]
async fn overwrite_payload(...) { ... let res = do_overwrite_payload(...) ... }

// src/common/update.rs:600-601, 647-648 — verb -> op mapping
let operation = CollectionUpdateOperations::PayloadOperation(PayloadOps::SetPayload(SetPayloadOp { ... }));   // do_set_payload
let operation = CollectionUpdateOperations::PayloadOperation(PayloadOps::OverwritePayload(SetPayloadOp { ... })); // do_overwrite_payload

// lib/shard/src/update.rs:105-118, 137-149 — dispatch
PayloadOps::SetPayload(sp) => { ... set_payload(segments, op_num, &payload, &points, &sp.key, hw_counter) ... }
PayloadOps::OverwritePayload(sp) => { ... overwrite_payload(segments, op_num, &payload, &points, hw_counter) ... }

// lib/segment/src/segment/entry.rs:737-748, 751-775 — segment entry: two distinct primitives
fn set_full_payload(...) { ... segment.payload_index.borrow_mut().overwrite_payload(internal_id, full_payload, hw_counter)?; ... }
fn set_payload(...) { ... segment.payload_index.borrow_mut().set_payload(internal_id, payload, key, hw_counter)?; ... }

// lib/segment/src/index/struct_payload_index.rs:909-948 — index layer
fn overwrite_payload(...) { self.payload.borrow_mut().overwrite(point_id, payload, hw_counter)?; ... }   // full replace
fn set_payload(...) { if let Some(key) = key { self.payload.borrow_mut().set_by_key(...) } else { self.payload.borrow_mut().set(...) }; ... }

// lib/segment/src/payload_storage/in_memory_payload_storage_impl.rs:67-90 — storage layer: THE semantic fork
fn overwrite(&mut self, point_id, payload, _hw_counter) -> OperationResult<()> {
    self.payload.insert(point_id, payload.to_owned());   // FULL REPLACEMENT
    Ok(())
}
fn set(&mut self, point_id, payload, _hw_counter) -> OperationResult<()> {
    match self.payload.get_mut(&point_id) {
        Some(point_payload) => point_payload.merge(payload),  // MERGE into existing payload
        None => { self.payload.insert(point_id, payload.to_owned()); }
    }
    Ok(())
}
